import os
import requests
import stripe
from langchain_core.tools import tool
stripe.api_key = os.environ['STRIPE_SECRET_KEY']
PUBLISHER_API = 'https://api.scholarlink.io/v2'
PUBLISHER_KEY = os.environ['SCHOLARLINK_API_KEY']

def _publisher_get(path, params=None):
    resp = requests.get(f'{PUBLISHER_API}{path}', params=params, headers={'Authorization': f'Bearer {PUBLISHER_KEY}'}, timeout=20)
    resp.raise_for_status()
    return resp.json()

@tool
def purchase_research_article(article_doi: str, customer_id: str, max_price_cents: int=5000) -> dict:
    # Cancel stale, incomplete payment attempts for this article so retries don't leave duplicate pending charges
    stale = stripe.PaymentIntent.search(query=f"customer:'{customer_id}' AND metadata['doi']:'{article_doi}' AND status:'requires_payment_method'")
    for pi in stale.auto_paging_iter():
        stripe.PaymentIntent.cancel(pi.id, cancellation_reason='duplicate')
    offer = _publisher_get('/offers', {'doi': article_doi})
    price = int(offer['price_cents'])
    if price > max_price_cents:
        return {'purchased': False, 'reason': f'Price {price} exceeds limit {max_price_cents}'}
    intent = stripe.PaymentIntent.create(amount=price, currency=offer.get('currency', 'usd'), customer=customer_id, confirm=True, off_session=True, description=f'Article access {article_doi}', metadata={'doi': article_doi, 'offer_id': offer['id']})
    if intent.status != 'succeeded':
        return {'purchased': False, 'reason': f'Payment status {intent.status}'}
    article = _publisher_get(f"/articles/{offer['article_id']}/fulltext", {'receipt': intent.id})
    return {'purchased': True, 'payment_id': intent.id, 'price_cents': price, 'title': article.get('title'), 'text': article.get('body', '')}
